// paintarena as a single program (executable built with `bun build --compile`).
//  - with no arguments it starts the site locally and opens the browser;
//  - with a command (compile, match, tournament) it works like the command line.
// The site is embedded in the executable: the file list is generated by scripts/dist.ts.

import { createServer } from "node:http";
import { readFileSync } from "node:fs";
import { spawn } from "node:child_process";

export interface SiteFile { path: string; type: string }
export type SiteFiles = Record<string, SiteFile>;

const DEFAULT_PORT = 51517;
const PING = "/__paintarena";

function detectLang(): "it" | "en" {
  const env = process.env.PAINTARENA_LANG ?? process.env.LANG ?? "";
  const loc = env || Intl.DateTimeFormat().resolvedOptions().locale;
  return loc.startsWith("it") ? "it" : "en";
}
const it = detectLang() === "it";

function openBrowser(url: string) {
  if (process.env.PAINTARENA_NO_BROWSER) return; // for tests and for anyone who prefers to open it by hand
  const [cmd, args] =
    process.platform === "win32" ? ["cmd", ["/c", "start", "", url]]
    : process.platform === "darwin" ? ["open", [url]]
    : ["xdg-open", [url]];
  try {
    spawn(cmd, args, { stdio: "ignore", detached: true }).unref();
  } catch {
    // no browser: the address is printed in the window anyway
  }
}

async function alreadyRunning(url: string): Promise<boolean> {
  try {
    const r = await fetch(url + PING.slice(1), { signal: AbortSignal.timeout(700) });
    return r.ok && (await r.text()) === "paintarena";
  } catch {
    return false;
  }
}

function serve(site: SiteFiles) {
  const port = Number(process.env.PAINTARENA_PORT ?? DEFAULT_PORT);
  // always the same port: the browser keeps code and progress per address
  const url = `http://127.0.0.1:${port}/`;
  return alreadyRunning(url).then((running) => {
    if (running) {
      console.log(it ? `paintarena è già aperto: ${url}` : `paintarena is already running: ${url}`);
      openBrowser(url);
      return;
    }
    const server = createServer((req, res) => {
      const path = decodeURIComponent(new URL(req.url ?? "/", url).pathname);
      if (path === PING) { res.writeHead(200, { "content-type": "text/plain" }).end("paintarena"); return; }
      const file = site[path === "/" ? "/index.html" : path];
      if (!file) { res.writeHead(404, { "content-type": "text/plain" }).end("404"); return; }
      res.writeHead(200, { "content-type": file.type, "cache-control": "no-cache" });
      res.end(readFileSync(file.path));
    });
    server.on("error", (e: NodeJS.ErrnoException) => {
      if (e.code === "EADDRINUSE")
        console.error(it
          ? `La porta ${port} è occupata da un altro programma. Scegline un'altra con la variabile PAINTARENA_PORT.`
          : `Port ${port} is used by another program. Pick another one with the PAINTARENA_PORT variable.`);
      else console.error(e.message);
      process.exit(1);
    });
    server.listen(port, "127.0.0.1", () => {
      console.log("paintarena");
      console.log(it ? `Il gioco è aperto nel browser: ${url}` : `The game is open in your browser: ${url}`);
      console.log(it ? "Per chiudere paintarena chiudi questa finestra (o premi Ctrl+C)." : "To quit paintarena close this window (or press Ctrl+C).");
      console.log(it
        ? "\nDalla riga di comando: paintarena compile|match|tournament … (paintarena help per l'elenco)"
        : "\nCommand line: paintarena compile|match|tournament … (paintarena help for the list)");
      openBrowser(url);
    });
  });
}

export async function runApp(site: SiteFiles) {
  const cmd = process.argv[2];
  if (cmd === undefined || cmd === "serve" || cmd === "gioca" || cmd === "play") await serve(site);
  else await import("./main.ts"); // command line: reads process.argv by itself
}
